    // To keep Halide's bounds inference safe while still writing the whole
    // domain [0..n-1]x[0..n-1], we wrap A_prev_param in a clamp-to-edge
    // boundary condition. This way, the stencil expression never reads
    // out of bounds, even though we later discard the boundary results via
    // a select().
    Func clamped_prev("clamped_prev");
    Func seidel_step("seidel_step");

    // Dynamic width/height queried from the ImageParam; they become
    // implicit scalar parameters of the JIT-compiled pipeline.
    Expr width  = A_prev_param.width();
    Expr height = A_prev_param.height();

    // Clamp-to-edge wrapper: safe for any (x, y).
    Expr clamped_x = clamp(x, 0, width  - 1);
    Expr clamped_y = clamp(y, 0, height - 1);
    clamped_prev(x, y) = A_prev_param(clamped_x, clamped_y);

    // 3x3 stencil on the clamped input.
    Expr s00 = clamped_prev(x - 1, y - 1);
    Expr s01 = clamped_prev(x,     y - 1);
    Expr s02 = clamped_prev(x + 1, y - 1);

    Expr s10 = clamped_prev(x - 1, y);
    Expr s11 = clamped_prev(x,     y);
    Expr s12 = clamped_prev(x + 1, y);

    Expr s20 = clamped_prev(x - 1, y + 1);
    Expr s21 = clamped_prev(x,     y + 1);
    Expr s22 = clamped_prev(x + 1, y + 1);

    Expr sum = s00 + s01 + s02 +
               s10 + s11 + s12 +
               s20 + s21 + s22;

    // Precompute the scalar factor 1/9 in C++, then lift it as a Halide Expr.
    const num_t scalar_factor =
        static_cast<num_t>(SCALAR_VAL(1.0)) /
        static_cast<num_t>(SCALAR_VAL(9.0));
    Expr factor = Expr(scalar_factor);
    Expr averaged = sum * factor;

    // Interior region: 1 <= x <= width - 2, 1 <= y <= height - 2.
    // For interior points, we use the stencil; for boundaries we
    // simply propagate the previous value unchanged.
    Expr is_interior =
        (x > 0) && (x < width  - 1) &&
        (y > 0) && (y < height - 1);

    seidel_step(x, y) = select(is_interior, averaged,
                               A_prev_param(x, y));

    // ------------------------------------------------------------------
    // Scheduling for better performance
    // ------------------------------------------------------------------
    //
    // Goal: good cache locality, SIMD utilization, and multicore
    // parallelism on a modern x64 CPU. We:
    //   - compute seidel_step at root once per time step,
    //   - tile the (x, y) domain for better cache reuse,
    //   - vectorize across the inner x dimension, and
    //   - parallelize across tiles in y.
    //
    constexpr int vec_width =
        (sizeof(num_t) == 4) ? 8 :   // float  -> use 8 lanes
        (sizeof(num_t) == 8) ? 4 :   // double -> use 4 lanes
        1;                           // other  -> leave scalar

    // Tile sizes chosen to give reasonably sized working sets; they
    // can be tuned further if desired.
    constexpr int tile_x = 256;
    constexpr int tile_y = 32;

    Var xo("xo"), yo("yo"), xi("xi"), yi("yi");

    seidel_step
        .compute_root()
        // 2D tiling for cache locality.
        .tile(x, y, xo, yo, xi, yi, tile_x, tile_y)
        // SIMD across x within a tile.
        .vectorize(xi, vec_width)
        // Parallelize tiles along y (and implicitly x tiles inside).
        .parallel(yo);

    // clamped_prev has no explicit schedule, so it is fully inlined
    // into seidel_step. Its clamp operations will also be vectorized
    // automatically along the xi dimension.

    // JIT-compile the per-time-step pipeline once.
    Target target = get_jit_target_from_environment();
    seidel_step.compile_jit(target);

    // Start timing
    auto start = std::chrono::high_resolution_clock::now();

    // Double-buffering over time steps.
    // We keep pointers to the "current" and "next" buffers and swap each step.
    Buffer<num_t, 2> *A_src = &A_cur;
    Buffer<num_t, 2> *A_dst = &A_next;

    for (int t = 0; t < tsteps; t++) {
        // Bind the current state as the input image for this step
        A_prev_param.set(*A_src);

        // Realize the full n x n domain into A_dst.
        // The Halide Func itself handles both interior updates and
        // unchanged boundaries via the 'select' above, so we don't
        // need separate boundary-copy loops.
        seidel_step.realize(*A_dst);

        // Swap the role of the buffers for the next iteration
        Buffer<num_t, 2> *tmp = A_src;
        A_src = A_dst;
        A_dst = tmp;
    }

    // After the loop, A_src points to the buffer with the final data
    Buffer<num_t, 2> &A_final = *A_src;

    // Stop timing
    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally dump the result to stderr (similar to the gemm example)
    using namespace std::string_literals;
