static void init_array(int n, Halide::Buffer<num_t, 2> A) {
    // In Halide coordinates: x == j (column), y == i (row)
    Var x("x"), y("y");
    Func init_A("init_A");

    // A[i][j] = ((DATA_TYPE) i*(j+2) + 2) / n;
    // Map to Halide as A(x, y) with x=j, y=i:
    init_A(x, y) = cast<num_t>(y * (x + 2) + 2) / cast<num_t>(n);

    // Simple but effective schedule for initialization:
    // - Vectorize across x (contiguous dimension).
    // - Parallelize across y (rows).
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    Var xo("xo"), xi("xi");
    init_A
        .split(x, xo, xi, vec_width)
        .vectorize(xi)
        .parallel(y);

    // Realize into the provided buffer.
    init_A.realize(A, target);
}

int main(int argc, char *argv[]) {
    // Problem size and time steps
    int n = N;
    int tsteps = TSTEPS;

    // Buffers for current and next time-step values.
    // We treat dimension 0 as column (j), dimension 1 as row (i),
    // so that C's A[i][j] maps to A(j, i).
    Buffer<num_t, 2> A_cur(n, n);
    Buffer<num_t, 2> A_next(n, n);

    // Initialize A_cur
    init_array(n, A_cur);

    // ImageParam to represent the "previous" time-step array in Halide
    ImageParam A_prev_param(type_of<num_t>(), 2, "A_prev");

    // Param to pass grid size into Halide; this allows the same JIT-compiled
    // pipeline to be reused for different problem sizes.
    Param<int> n_param("n");

    // Vars for spatial indices
    Var x("x"), y("y");

    // One time-step of the 2D Seidel/Jacobi-like update, expressed in Halide.
    //
    // Original C update (for interior points 1..n-2):
    //
    // A[i][j] = (A[i-1][j-1] + A[i-1][j] + A[i-1][j+1]
    //            + A[i][j-1] + A[i][j] + A[i][j+1]
    //            + A[i+1][j-1] + A[i+1][j] + A[i+1][j+1]) / 9.0;
    //
    // Mapping to Halide coordinates: i -> y, j -> x, A[i][j] -> A_prev_param(x, y).
    Func seidel_step("seidel_step");

    // Wrap the previous time-step in a clamp-to-edge boundary condition so that
    // stencil accesses at x-1, x+1, y-1, y+1 are always in-bounds, even at
    // the outermost boundary. This satisfies Halide's bounds inference rules.
    Func A_prev_bc = Halide::BoundaryConditions::repeat_edge(A_prev_param);

    Expr denom = cast<num_t>(SCALAR_VAL(9.0));

    // Predicate that is true only for interior points 1..n-2 in both dimensions.
    Expr interior =
        (x > 0) && (x < n_param - 1) &&
        (y > 0) && (y < n_param - 1);

    // 3x3 stencil sum around (x, y) using the clamped previous state.
    Expr sum =
        A_prev_bc(x - 1, y - 1) +
        A_prev_bc(x - 1, y    ) +
        A_prev_bc(x - 1, y + 1) +
        A_prev_bc(x,     y - 1) +
        A_prev_bc(x,     y    ) +
        A_prev_bc(x,     y + 1) +
        A_prev_bc(x + 1, y - 1) +
        A_prev_bc(x + 1, y    ) +
        A_prev_bc(x + 1, y + 1);

    // For interior points, apply the 3x3 average; for boundary points,
    // keep the value from the previous time step unchanged. This matches
    // the original C loops, which never update the boundaries.
    seidel_step(x, y) = select(interior, sum / denom,
                               A_prev_param(x, y));

