    // Scheduling for seidel_step
    // -------------------------
    //
    // We want to:
    // - Exploit data locality via tiling.
    // - Vectorize along the contiguous x dimension.
    // - Parallelize across tiles in the y dimension to use all cores.
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Tile sizes (can be tuned for specific cache hierarchies).
    constexpr int tile_x = 32;
    constexpr int tile_y = 32;

    Var xo("xo"), yo("yo"), xi("xi"), yi("yi");

    seidel_step
        // 2D tiling for locality.
        .tile(x, y, xo, yo, xi, yi, tile_x, tile_y)
        // Vectorize across the innermost x dimension.
        .vectorize(xi, vec_width)
        // Parallelize across tiles in the y direction.
        .parallel(yo);

    // A_prev_bc is a simple clamped view of A_prev_param; we leave it
    // inlined (default schedule) so that the clamping arithmetic is
    // fused directly into the seidel_step loops.

    // JIT-compile the per-time-step pipeline once
    seidel_step.compile_jit(target);

    // Bind the grid size parameter once (constant across all time steps).
    n_param.set(n);

    // Start timing
    auto start = std::chrono::high_resolution_clock::now();

    // Double-buffering over time steps.
    // We keep pointers to the "current" and "next" buffers and swap each step.
    Buffer<num_t, 2> *A_src = &A_cur;
    Buffer<num_t, 2> *A_dst = &A_next;

    for (int t = 0; t < tsteps; t++) {
        // Bind the current state as the input image for this step
        A_prev_param.set(*A_src);

        // Compute the full n x n output grid in one Halide call.
        seidel_step.realize(*A_dst);

