    Var i("i"), j("j");
    Func init_A("init_A");

    // A[i][j] = ((DATA_TYPE) i*(j+2) + 2) / n;
    // Map to Halide as A(j, i), so j is the innermost, contiguous dimension.
    init_A(j, i) = cast<num_t>(i * (j + 2) + 2) / cast<num_t>(n);

    // Simple CPU schedule: parallel over rows (i), vectorize over columns (j).
    Target target = get_host_target();
    const int vec_width = natural_vector_size(type_of<num_t>(), target);

    init_A
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    // JIT-compile and realize into the provided buffer.
    init_A.compile_jit(target);
    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size and time steps
    int n = N;
    int tsteps = TSTEPS;

    // Buffers for current and next time-step values.
    // We treat dimension 0 as column (j), dimension 1 as row (i),
    // so that C's A[i][j] maps to A(j, i).
    Buffer<num_t, 2> A_cur(n, n);
    Buffer<num_t, 2> A_next(n, n);

    // Initialize A_cur
    init_array(n, A_cur);

    // ImageParam to represent the "previous" time-step array in Halide
    ImageParam A_prev_param(type_of<num_t>(), 2, "A_prev");

    // Vars for spatial indices
    Var x("x"), y("y");

    // One time-step of the 2D Seidel/Jacobi-like update, expressed in Halide.
    //
    // Original C-like update (for interior points 1..n-2):
    //
    // A[i][j] = (A[i-1][j-1] + A[i-1][j] + A[i-1][j+1]
    //            + A[i][j-1]   + A[i][j]   + A[i][j+1]
    //            + A[i+1][j-1] + A[i+1][j] + A[i+1][j+1]) / 9.0;
    //
    // Mapping to Halide coordinates: i -> y, j -> x, A[i][j] -> A_prev_param(x, y).
    //
    // We also incorporate the boundary copy into the Halide pipeline:
    //  - interior (1..n-2, 1..n-2): apply the 3x3 stencil
    //  - boundary: keep A[x,y] unchanged (copy from previous time step).
    //
    // To avoid out-of-bounds accesses in the stencil, we wrap A_prev_param with
    // BoundaryConditions::repeat_edge and use that only for the stencil reads.
    //
    // This lets us realize the full n x n output in Halide, eliminating the
    // explicit C++ boundary-copy loops while preserving the original semantics
    // (boundaries remain unchanged each time step).
    Func padded("A_prev_padded");
    {
        // Repeat-edge boundary condition gives a well-defined value for all
        // (x,y), but for interior points the values are identical to A_prev.
        Func padded_bc = Halide::BoundaryConditions::repeat_edge(A_prev_param);
        padded(x, y) = padded_bc(x, y);
    }

    Func seidel_step("seidel_step");

    // Denominator as in the original code: divide by 9.0 (via SCALAR_VAL).
    Expr denom = cast<num_t>(SCALAR_VAL(9.0));

    // Compute boundary extents from the ImageParam, so the pipeline does not
    // hard-code n and remains valid for any buffer size bound at runtime.
    Expr x_min = A_prev_param.dim(0).min();
    Expr x_max = x_min + A_prev_param.dim(0).extent() - 1;
    Expr y_min = A_prev_param.dim(1).min();
    Expr y_max = y_min + A_prev_param.dim(1).extent() - 1;

    // Boundary predicate: true on the outermost rows/columns.
    Expr is_boundary =
        (x == x_min) || (x == x_max) ||
        (y == y_min) || (y == y_max);

    // 3x3 stencil sum using the padded (repeat-edge) input.
    Expr sum =
        padded(x - 1, y - 1) +
        padded(x - 1, y    ) +
        padded(x - 1, y + 1) +
        padded(x,     y - 1) +
        padded(x,     y    ) +
        padded(x,     y + 1) +
        padded(x + 1, y - 1) +
        padded(x + 1, y    ) +
        padded(x + 1, y + 1);

    // Full update:
    //  - interior: average of 3x3 stencil
    //  - boundary: copy previous value (keeps boundaries unchanged in time)
    seidel_step(x, y) = select(is_boundary,
                               A_prev_param(x, y),
                               sum / denom);

    // --------------------------------------------------------------------
    // Optimized schedule for the per-time-step pipeline
    // --------------------------------------------------------------------
    Target target = get_host_target();
    const int vec_width = natural_vector_size(type_of<num_t>(), target);

    // Use a cache-friendly tiling in x,y, vectorize across x (innermost),
    // and parallelize across tiles in y.
    Var xo("xo"), yo("yo"), xi("xi"), yi("yi");

    const int tile_x = 32;  // columns per tile
    const int tile_y = 32;  // rows per tile

    seidel_step
        .compute_root()
        // Tile the 2D iteration space.
        .tile(x, y, xo, yo, xi, yi, tile_x, tile_y)
        // Vectorize along contiguous x inside each tile.
        .vectorize(xi, vec_width)
        // Parallelize across tiles in the y dimension.
        .parallel(yo);

    // Keep the boundary-condition func inline and vectorized within tiles
    // to avoid unnecessary storage and maximize locality.
    padded
        .compute_at(seidel_step, yo)
        .vectorize(x, vec_width);

    // JIT-compile the per-time-step pipeline once for the host target.
    seidel_step.compile_jit(target);

    // Start timing
    auto start = std::chrono::high_resolution_clock::now();

    // Double-buffering over time steps.
    // We keep pointers to the "current" and "next" buffers and swap each step.
    Buffer<num_t, 2> *A_src = &A_cur;
    Buffer<num_t, 2> *A_dst = &A_next;

    for (int t = 0; t < tsteps; t++) {
        // Bind the current state as the input image for this step
        A_prev_param.set(*A_src);

        // Realize the entire n x n grid in one pass. The Halide pipeline
        // takes care of:
        //  - updating interior points (stencil)
        //  - copying boundary points unchanged
        seidel_step.realize(*A_dst);

        // Swap the role of the buffers for the next iteration
        Buffer<num_t, 2> *tmp = A_src;
        A_src = A_dst;
        A_dst = tmp;
    }

    // After the loop, A_src points to the buffer with the final data
    Buffer<num_t, 2> &A_final = *A_src;

    // Stop timing
    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally dump the result to stderr (similar to the gemm example)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // Recall: A[i][j] in C is A_final(j, i) in Halide.
                std::cerr << A_final(j, i) << '\n';
            }
        }
    }

    // Print elapsed time in seconds with 6 decimal places
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
